\n// path: test/fitur/dompet/page/dompet_page_test.dart\nimport 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport 'package:flutter_test/flutter_test.dart';\nimport 'package:mockito/mockito.dart';\nimport 'package:wifi/fitur/dompet/model/dompet_model.dart';\nimport 'package:wifi/fitur/dompet/page/dompet_page.dart';\nimport 'package:wifi/fitur/dompet/provider/dompet_provider.dart';\n\n// Mock class for DompetNotifier\nclass MockDompetNotifier extends Mock implements DompetNotifier {\n  @override\n  Future<DompetState> build() async {\n    return const DompetState(\n      wallets: [],\n      totalSaldo: 0,\n      totalSaldoPositif: 0,\n      totalSaldoNegatif: 0,\n    );\n  }\n}\n\nvoid main() {\n  group('DompetPage', () {\n    late ProviderContainer container;\n    late MockDompetNotifier mockDompetNotifier;\n\n    setUp(() {\n      mockDompetNotifier = MockDompetNotifier();\n      container = ProviderContainer(\n        overrides: [\n          dompetProvider.overrideWith(() => mockDompetNotifier),\n        ],\n      );\n    });\n\n    tearDown(() {\n      container.dispose();\n    });\n\n    testWidgets('01. Menampilkan CircularProgressIndicator saat loading', (tester) async {\n      when(mockDompetNotifier.build()).thenAnswer((_) async => const DompetState());\n\n      await tester.pumpWidget(\n        UncontrolledProviderScope(\n          container: container,\n          child: const MaterialApp(home: DompetPage()),\n        ),\n      );\n\n      expect(find.byType(CircularProgressIndicator), findsOneWidget);\n    });\n\n    testWidgets('02. Menampilkan pesan error saat terjadi kesalahan', (tester) async {\n      final exception = Exception('Gagal memuat data');\n      when(mockDompetNotifier.build()).thenThrow(exception);\n\n      await tester.pumpWidget(\n        UncontrolledProviderScope(\n          container: container,\n          child: const MaterialApp(home: DompetPage()),\n        ),\n      );\n\n      await tester.pumpAndSettle();\n\n      expect(find.text('Terjadi kesalahan: \$exception'), findsOneWidget);\n    });\n\n    testWidgets('03. Menampilkan pesan saat tidak ada dompet', (tester) async {\n      when(mockDompetNotifier.build()).thenAnswer((_) async => const DompetState(wallets: []));\n\n      await tester.pumpWidget(\n        UncontrolledProviderScope(\n          container: container,\n          child: const MaterialApp(home: DompetPage()),\n        ),\n      );\n        await tester.pumpAndSettle();\n\n      expect(find.text('Tidak ada dompet ditemukan.'), findsOneWidget);\n    });\n\n    testWidgets('04. Menampilkan daftar dompet', (tester) async {\n      final dompetList = [\n        DompetModel(id: '1', nama: 'Dompet 1', saldo: 100000, dibuatPada: DateTime.now(), diperbaruiPada: DateTime.now()),\n        DompetModel(id: '2', nama: 'Dompet 2', saldo: -50000, dibuatPada: DateTime.now(), diperbaruiPada: DateTime.now()),\n      ];\n      when(mockDompetNotifier.build()).thenAnswer((_) async => DompetState(\n        wallets: dompetList,\n        totalSaldo: 50000,\n        totalSaldoPositif: 100000,\n        totalSaldoNegatif: -50000,\n      ));\n\n      await tester.pumpWidget(\n        UncontrolledProviderScope(\n          container: container,\n          child: const MaterialApp(home: DompetPage()),\n        ),\n      );\n      await tester.pumpAndSettle();\n\n      expect(find.byType(WalletCard), findsNWidgets(2));\n      expect(find.text('Dompet 1'), findsOneWidget);\n      expect(find.text('Dompet 2'), findsOneWidget);\n    });\n  });\n}\n